window.Analytics = (() => {
 const {e,icon,button,field,input,select}=UI;
 const sessions=new Map();
 let tool='browser',config=false;
 const labels={browser:'JupyterLite',jupyter:'JupyterLab',duckdb:'DuckDB UI',rstudio:'RStudio Server'};
 const isHTTP=()=>['http:','https:'].includes(location.protocol);
 const endpoint=()=>tool==='browser'?'analytics/lab/index.html':Cousins.db.analyticsConnections?.[tool];
 function header(){return `<header class="page-header"><div class="header-identity">${UI.breadcrumbs('Analytics')}<h1>Analytics</h1><div class="tool-label"><span>${tool==='browser'?'Browser Python':labels[tool]}</span><span id="analytics-state" role="status">Not opened</span></div></div><div class="actions">${select('analytics-tool',tool,Object.entries(labels).map(([value,label])=>({value,label})),'data-analytics-tool aria-label="Analytics tool"')}${button('Connection','analytics-config',{icon:'sliders'})}</div></header>`;}
 function inspector(){return `<aside class="inspector"><header><h2>Tool connection</h2>${button('Close connection settings','analytics-config',{icon:'close',iconOnly:true})}</header><form id="analytics-connection" class="inspector-body">${field('Interface',select('tool',tool==='browser'?'jupyter':tool,['jupyter','duckdb','rstudio'].map(value=>({value,label:labels[value]}))))}${field('Server URL',input('endpoint',tool==='browser'?'':endpoint()||'','url','placeholder="http://localhost:8888/lab" required'))}<p class="field-hint">Sign in within the tool. Keep authentication tokens out of the saved URL.</p><button class="btn primary" type="submit">Save connection</button><p class="field-hint">JupyterLite saves files in this browser. Download notebooks to keep a separate copy.</p></form></aside>`;}
 function render(){return `<div class="analytics-page">${header()}<div class="analytics-tools"><div class="actions">${button('Files','analytics-files',{icon:'folder'})}${button('New notebook','analytics-notebook',{icon:'plus'})}${button('New folder','analytics-folder',{icon:'folder'})}${button('New file','analytics-new-file',{icon:'file'})}</div><div class="actions"><a id="analytics-open" class="btn quiet" target="_blank" rel="noopener noreferrer">Open separately ${icon('external')}</a>${button('Reload','analytics-retry',{icon:'undo'})}</div></div><div class="analytics-work"><div class="lab-container"><div id="lab-status" class="lab-status" role="status"></div><div id="lab-mount"></div></div><div id="analytics-inspector" ${config?'':'hidden'}>${config?inspector():''}</div></div></div>`;}
 function status(session){if(session!==sessions.get(tool))return;const state=document.getElementById('analytics-state'),notice=document.getElementById('lab-status');if(!state||!notice)return;state.textContent=session.state==='ready'?'Workspace ready':session.state==='external'?'External tool':session.state==='loading'?'Opening workspace':session.state==='slow'?'Taking longer than expected':'Workspace unavailable';notice.hidden=['ready','external'].includes(session.state);notice.innerHTML=session.state==='loading'?'<span class="skeleton"></span><span>Loading the notebook workspace. The kernel starts when you run a cell.</span>':`<strong>${session.state==='slow'?'The notebook workspace has not finished loading.':'The notebook workspace could not open.'}</strong><span>${e(session.message||'Keep this page open, reload, or open the workspace separately.')}</span>`;}
 async function ready(session){try{const app=session.frame.contentWindow.jupyterapp;if(!app){if(session.state==='loading'||session.state==='slow')session.timer=setTimeout(()=>ready(session),400);return;}await app.started;await app.restored;if(session.closed)return;session.app=app;session.state='ready';clearTimeout(session.timeout);const doc=session.frame.contentDocument;if(!doc.getElementById('cousins-lab-style')){const link=doc.createElement('link');link.id='cousins-lab-style';link.rel='stylesheet';link.href='../cousins-lab.css';doc.head.append(link);}await syncTheme(session);status(session);}catch(error){session.state='failed';session.message=error.message;status(session);}}
 async function syncTheme(session=sessions.get('browser')){if(!session?.app)return;try{await session.app.commands.execute('apputils:change-theme',{theme:document.documentElement.dataset.theme==='dark'?'JupyterLab Dark':'JupyterLab Light'});}catch{}}
 function mount(){const host=document.getElementById('lab-mount');if(!host)return;const url=endpoint();document.getElementById('analytics-open').href=url||'#';document.getElementById('analytics-open').hidden=!url;const native=tool==='browser';document.querySelectorAll('.analytics-tools [data-action]').forEach(b=>{if(b.dataset.action!=='analytics-retry')b.hidden=!native;});for(const [key,s]of sessions)s.frame.hidden=key!==tool;
 if(!url||native&&!isHTTP()){document.getElementById('analytics-state').textContent='Setup required';const n=document.getElementById('lab-status');n.hidden=false;n.innerHTML=native?'<strong>Serve this folder to open Analytics.</strong><span>Run <code>python3 serve.py</code> in the project folder, then open <a href="http://127.0.0.1:8000/#analytics" target="_blank" rel="noopener">127.0.0.1:8000</a>. The browser Python runtime requires HTTP.</span>':`<strong>Connect ${e(labels[tool])}</strong>${button('Configure connection','analytics-config',{primary:true})}`;return;}
 let session=sessions.get(tool);if(session&&session.url!==url){session.closed=true;clearTimeout(session.timer);clearTimeout(session.timeout);session.frame.remove();sessions.delete(tool);session=null;}
 if(!session){const frame=document.createElement('iframe');frame.className='lab-frame';frame.title=labels[tool]+' workspace';frame.referrerPolicy='no-referrer';session={frame,url,state:'loading',app:null,closed:false};sessions.set(tool,session);frame.addEventListener('load',()=>{if(native)ready(session);else{session.state='external';session.message='';status(session);}});frame.addEventListener('error',()=>{session.state='failed';session.message='Check the server address and its embedding policy.';status(session);});frame.src=url;host.append(frame);session.timeout=setTimeout(()=>{if(session.state==='loading'){session.state='slow';status(session);}},30000);}
 session.frame.hidden=false;status(session);syncTheme();
 }
 function refresh(){const page=document.querySelector('.analytics-page');if(!page)return;page.querySelector('.page-header').outerHTML=header();const slot=document.getElementById('analytics-inspector');slot.hidden=!config;slot.innerHTML=config?inspector():'';mount();}
 async function command(id,args={}){const s=sessions.get('browser');if(!s?.app){App.toast('Wait for the notebook workspace to finish opening.');return;}try{await s.app.commands.execute(id,args);}catch(error){App.toast(error.message||'This action is unavailable. Use the Jupyter File menu.');}}
 function action(action){if(action==='analytics-config'){config=!config;refresh();return true;}if(action==='analytics-files'){command('application:toggle-left-area');return true;}if(action==='analytics-folder'){command('filebrowser:create-new-directory');return true;}if(action==='analytics-new-file'){command('filebrowser:create-new-file',{ext:'.txt'});return true;}if(action==='analytics-notebook'){command('notebook:create-new');return true;}if(action==='analytics-retry'){App.confirm('Reload workspace?','Save any changes in the notebook before reloading.','Reload',()=>{const s=sessions.get(tool);if(s){s.closed=true;clearTimeout(s.timer);clearTimeout(s.timeout);s.frame.remove();sessions.delete(tool);}mount();});return true;}return false;}
 function setTool(value){tool=value;refresh();}
 function connect(form){const data=new FormData(form),type=data.get('tool');let url;try{url=new URL(data.get('endpoint'));if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error();if([...url.searchParams.keys()].some(k=>/token|password|secret/i.test(k))){App.toast('Remove credentials from the URL and sign in inside the tool.');return;}}catch{App.toast('Enter an HTTP or HTTPS server URL.');return;}Cousins.db.analyticsConnections ||= {};Cousins.db.analyticsConnections[type]=url.href;Cousins.save();tool=type;config=false;refresh();}
 return {render,mount,action,setTool,connect,syncTheme};
})();
